import { randomInt } from 'node:crypto';
import bcrypt from 'bcryptjs';

/**
 * Staff password hashing (SR-09): bcrypt, cost 12. Passwords are generated by
 * the system, at least 12 characters, and never chosen by the user.
 *
 * bcrypt only reads the first 72 bytes of a password, so a longer one is
 * refused instead of being silently cut short.
 */

const BCRYPT_COST = 12;
const MAX_PASSWORD_BYTES = 72;
export const MIN_PASSWORD_LENGTH = 12;

// No 0/O or 1/l/I, so a password read out loud or copied by hand is not misread.
const PASSWORD_ALPHABET =
  'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';

/** A random password of the given length (at least MIN_PASSWORD_LENGTH). */
export function generatePassword(length = 20): string {
  if (!Number.isInteger(length) || length < MIN_PASSWORD_LENGTH) {
    throw new Error(
      `A generated password must be at least ${MIN_PASSWORD_LENGTH} characters.`,
    );
  }
  let password = '';
  for (let i = 0; i < length; i++) {
    password += PASSWORD_ALPHABET[randomInt(PASSWORD_ALPHABET.length)];
  }
  return password;
}

export async function hashPassword(password: string): Promise<string> {
  if (password.length < MIN_PASSWORD_LENGTH) {
    throw new Error(
      `A password must be at least ${MIN_PASSWORD_LENGTH} characters.`,
    );
  }
  if (Buffer.byteLength(password) > MAX_PASSWORD_BYTES) {
    throw new Error(`A password must be at most ${MAX_PASSWORD_BYTES} bytes.`);
  }
  return bcrypt.hash(password, BCRYPT_COST);
}

// Compared against when the username does not exist, so a wrong username takes
// as long as a wrong password and the response time does not reveal accounts.
let unknownAccountHash: Promise<string> | undefined;

/**
 * True when the password matches the hash. Pass `null` for an unknown account:
 * the work of a real check is still done and the answer is always false.
 */
export async function verifyPassword(
  password: string,
  hash: string | null,
): Promise<boolean> {
  if (hash === null) {
    unknownAccountHash ??= bcrypt.hash('unknown-account', BCRYPT_COST);
    await bcrypt.compare(password, await unknownAccountHash);
    return false;
  }
  if (Buffer.byteLength(password) > MAX_PASSWORD_BYTES) return false;
  return bcrypt.compare(password, hash);
}
